methods.source:
public async discoverTaxonomies(scope: FigshareScope): Promise<FigshareTaxonomySummary[]> {
    const response = await firstValueFrom(
      this.http.get(`${this.figshareUrl}/catalogues`, { ...this.getJsonRequestOptions(), params: { scope } })
    );
    return this.unwrap<FigshareTaxonomySummary[]>(response as ApiResponse<FigshareTaxonomySummary[]>) ?? [];
  }

async discoverTaxonomies(scope: FigshareScope): Promise<void> {
    this.discovering = true;
    this.wizardError = '';
    try {
      this.taxonomies = await this.api.discoverTaxonomies(scope);
    } catch (err) {
      this.taxonomies = [];
      this.wizardError = this.errorText('figshare-vocab-error-discover', err);
      this.logger.error(this.wizardError);
    } finally {
      this.discovering = false;
    }
  }

public async listSources(scope?: string): Promise<PagedResult<FigshareSourceSummary>> {
    const params: Record<string, string> = {};
    if (scope) {
      params['scope'] = scope;
    }
    const response = await firstValueFrom(
      this.http.get(`${this.figshareUrl}/sources`, { ...this.getJsonRequestOptions(), params })
    );
    return this.unwrapList<FigshareSourceSummary>(response);
  }

private async loadSources(): Promise<void> {
    this.sourcesLoading = true;
    try {
      const result = await this.api.listSources(this.scopeFilter || undefined);
      this.sources = result.records;
      this.sourceTotal = result.total;
    } catch (err) {
      this.error = this.errorText('figshare-vocab-error-load-sources', err);
      this.logger.error(this.error);
    } finally {
      this.sourcesLoading = false;
    }
  }

protected override async initComponent(): Promise<void> {
    await Promise.all([this.loadSources(), this.loadCrosswalks()]);
  }

async showTab(view: FigshareView): Promise<void> {
    this.view = view;
    this.message = '';
    this.error = '';
    if (view === 'sources') {
      await this.loadSources();
    } else if (view === 'crosswalks') {
      await this.loadCrosswalks();
    } else if (view === 'history') {
      await this.loadSyncRuns();
    }
  }

async onScopeFilterChanged(scope: '' | 'public' | 'account'): Promise<void> {
    this.scopeFilter = scope;
    await this.loadSources();
  }

async applyPreview(): Promise<void> {
    if (!this.preview) {
      return;
    }
    this.applying = true;
    this.previewError = '';
    try {
      const result = await this.api.applyPreview(this.preview.runId, {
        remoteHash: this.preview.remoteHash,
        approvedProposalIds: this.approvedProposalIds,
      });
      this.message = this.t(
        'figshare-vocab-apply-complete',
        'Applied: {{created}} added, {{updated}} changed, {{historical}} historical, {{mappings}} mappings.',
        {
          created: result.categories.created,
          updated: result.categories.updated,
          historical: result.categories.historical,
          mappings: result.mappings.created,
        }
      );
      this.preview = null;
      this.view = 'sources';
      await Promise.all([this.loadSources(), this.loadCrosswalks()]);
    } catch (err) {
      this.previewError = this.errorText('figshare-vocab-error-apply', err);
      this.logger.error(this.previewError);
    } finally {
      this.applying = false;
    }
  }

public async listSourceCategories(sourceId: string, query: {
    q?: string;
    includeHistorical?: boolean;
    selectableOnly?: boolean;
    limit?: number;
    offset?: number;
  } = {}): Promise<PagedResult<FigshareSourceCategory>> {
    const response = await firstValueFrom(
      this.http.get(`${this.figshareUrl}/sources/${encodeURIComponent(sourceId)}/categories`, {
        ...this.getJsonRequestOptions(),
        params: this.toParams(query)
      })
    );
    return this.unwrapList<FigshareSourceCategory>(response);
  }

private async loadCategories(): Promise<void> {
    if (!this.sourceId) {
      return;
    }
    const requestId = ++this.categoryRequestId;
    this.categoriesLoading = true;
    try {
      const result = await this.api.listSourceCategories(this.sourceId, {
        q: String(this.targetSearchControl.value ?? '').trim() || undefined,
        includeHistorical: this.includeHistorical,
        limit: PAGE_SIZE,
      });
      if (requestId !== this.categoryRequestId) {
        return;
      }
      this.categories = result.records;
      this.categoryTotal = result.total;
      this.targetErrorMessage = '';
    } catch (err) {
      this.logger.error('Failed to load Figshare categories', err);
      this.targetErrorMessage = this.t(
        'figshare-vocab-error-load-categories',
        'The Figshare categories could not be loaded.'
      );
    } finally {
      if (requestId === this.categoryRequestId) {
        this.categoriesLoading = false;
      }
    }
  }

async ngOnInit(): Promise<void> {
    this.localSearchControl.valueChanges
      .pipe(debounceTime(SEARCH_DEBOUNCE_MS), distinctUntilChanged(), takeUntilDestroyed(this.destroyRef))
      .subscribe(() => void this.loadLocalEntries());
    this.targetSearchControl.valueChanges
      .pipe(debounceTime(SEARCH_DEBOUNCE_MS), distinctUntilChanged(), takeUntilDestroyed(this.destroyRef))
      .subscribe(() => void this.loadCategories());

    const loads: Array<Promise<void>> = [this.loadCategories()];
    if (this.localTerm) {
      loads.push(this.loadCurrentTargets(this.localTerm.id, this.localTerm.value));
    } else {
      loads.push(this.loadLocalEntries());
    }
    await Promise.all(loads);
  }

async toggleIncludeHistorical(includeHistorical: boolean): Promise<void> {
    this.includeHistorical = includeHistorical;
    this.selectedCategoryId = '';
    await this.loadCategories();
  }

public async listSyncRuns(sourceId?: string): Promise<PagedResult<FigshareSyncRunSummary>> {
    const params: Record<string, string> = {};
    if (sourceId) {
      params['sourceId'] = sourceId;
    }
    const response = await firstValueFrom(
      this.http.get(`${this.figshareUrl}/sync-runs`, { ...this.getJsonRequestOptions(), params })
    );
    return this.unwrapList<FigshareSyncRunSummary>(response);
  }

private async loadSyncRuns(): Promise<void> {
    this.historyLoading = true;
    try {
      const result = await this.api.listSyncRuns(this.historySourceId || undefined);
      this.syncRuns = result.records;
    } catch (err) {
      this.error = this.errorText('figshare-vocab-error-load-history', err);
      this.logger.error(this.error);
    } finally {
      this.historyLoading = false;
    }
  }

async showHistoryFor(source: FigshareSourceSummary): Promise<void> {
    this.historySourceId = source.id;
    this.view = 'history';
    await this.loadSyncRuns();
  }

public async listLocalVocabularies(): Promise<FigshareLocalVocabulary[]> {
    const response = await firstValueFrom(
      this.http.get(`${this.brandingAndPortalUrl}/api/vocabulary`, {
        ...this.getJsonRequestOptions(),
        params: { limit: '200' }
      })
    );
    return this.unwrapList<FigshareLocalVocabulary>(response).records
      .filter((vocabulary) => vocabulary.source !== 'external');
  }

async startImport(): Promise<void> {
    this.wizardError = '';
    this.taxonomies = [];
    this.view = 'import';
    try {
      this.localVocabularies = await this.api.listLocalVocabularies();
    } catch (err) {
      this.wizardError = this.errorText('figshare-vocab-error-load-vocabularies', err);
    }
  }

public async createPreview(input: {
    scope: FigshareScope;
    taxonomyId: string;
    sourceId?: string;
    crosswalkId?: string;
    localVocabularyId?: string;
    createLocalClone?: boolean;
    localCloneName?: string;
    localCloneSlug?: string;
  }): Promise<FigsharePreview> {
    const response = await firstValueFrom(
      this.http.post(`${this.figshareUrl}/previews`, input, this.getJsonRequestOptions())
    );
    return this.unwrap<FigsharePreview>(response as ApiResponse<FigsharePreview>);
  }

async generatePreview(request: FigshareImportRequest): Promise<void> {
    this.generating = true;
    this.wizardError = '';
    try {
      const preview = await this.api.createPreview(request);
      await this.openPreview(preview.runId);
    } catch (err) {
      this.wizardError = this.errorText('figshare-vocab-error-preview', err);
      this.logger.error(this.wizardError);
    } finally {
      this.generating = false;
    }
  }

public async createSourcePreview(sourceId: string, body: { localVocabularyId?: string; crosswalkId?: string }): Promise<FigsharePreview> {
    const response = await firstValueFrom(
      this.http.post(`${this.figshareUrl}/sources/${encodeURIComponent(sourceId)}/preview`, body, this.getJsonRequestOptions())
    );
    return this.unwrap<FigsharePreview>(response as ApiResponse<FigsharePreview>);
  }

async resyncSource(source: FigshareSourceSummary): Promise<void> {
    this.clearAlerts();
    this.previewError = '';
    this.applying = false;
    this.busySourceId = source.id;
    try {
      const preview = await this.api.createSourcePreview(source.id, {});
      await this.openPreview(preview.runId);
    } catch (err) {
      this.error = this.errorText('figshare-vocab-error-preview', err);
      this.logger.error(this.error);
    } finally {
      this.busySourceId = '';
    }
  }

public async cloneSource(sourceId: string, body: { name: string; slug?: string }): Promise<{ localVocabularyId: string; crosswalkId: string; entries: number }> {
    const response = await firstValueFrom(
      this.http.post(`${this.figshareUrl}/sources/${encodeURIComponent(sourceId)}/clone`, body, this.getJsonRequestOptions())
    );
    return this.unwrap(response as ApiResponse<{ localVocabularyId: string; crosswalkId: string; entries: number }>);
  }

async cloneSource(source: FigshareSourceSummary): Promise<void> {
    this.clearAlerts();
    const name = this.t('figshare-vocab-clone-name-suffix', '{{name}} (local copy)', { name: source.displayName });
    this.busySourceId = source.id;
    try {
      const clone = await this.api.cloneSource(source.id, { name });
      this.message = this.t('figshare-vocab-clone-created', 'Editable clone created with {{count}} terms.', {
        count: clone.entries,
      });
      await this.loadCrosswalks();
      this.view = 'crosswalks';
    } catch (err) {
      this.error = this.errorText('figshare-vocab-error-clone', err);
      this.logger.error(this.error);
    } finally {
      this.busySourceId = '';
    }
  }

public async getPreview(runId: string, query: {
    view?: 'proposals' | 'diff';
    changeClass?: string;
    matchType?: string;
    q?: string;
    unresolvedOnly?: boolean;
    historicalOnly?: boolean;
    limit?: number;
    offset?: number;
  } = {}): Promise<FigsharePagedPreview> {
    const params: Record<string, string> = {};
    for (const [key, value] of Object.entries(query)) {
      if (value !== undefined && value !== null && value !== '') {
        params[key] = String(value);
      }
    }
    const response = await firstValueFrom(
      this.http.get(`${this.figshareUrl}/previews/${encodeURIComponent(runId)}`, {
        ...this.getJsonRequestOptions(),
        params
      })
    );
    return this.unwrap<FigsharePagedPreview>(response as ApiResponse<FigsharePagedPreview>);
  }

private async loadPreview(runId: string, seedApprovals = false): Promise<void> {
    this.previewLoading = true;
    try {
      const preview = await this.api.getPreview(runId, {
        view: this.previewFilters.view,
        q: this.previewFilters.q || undefined,
        changeClass: this.previewFilters.changeClass || undefined,
        unresolvedOnly: this.previewFilters.unresolvedOnly || undefined,
        historicalOnly: this.previewFilters.historicalOnly || undefined,
        offset: this.previewFilters.offset,
        limit: 50,
      });
      this.preview = preview;
      if (seedApprovals || this.approvedProposalIds.length === 0) {
        // Exact-code and identity proposals arrive preselected; label suggestions do not.
        this.approvedProposalIds = (preview.page.records as Array<{ proposalId?: string; preselected?: boolean }>)
          .filter(record => record.preselected === true && !!record.proposalId)
          .map(record => String(record.proposalId));
      }
      this.previewError = '';
    } catch (err) {
      this.previewError = this.errorText('figshare-vocab-error-preview', err);
      this.logger.error(this.previewError);
    } finally {
      this.previewLoading = false;
    }
  }

private async openPreview(runId: string): Promise<void> {
    this.previewFilters = {
      view: 'proposals',
      q: '',
      changeClass: '',
      unresolvedOnly: false,
      historicalOnly: false,
      offset: 0,
    };
    this.approvedProposalIds = [];
    this.view = 'preview';
    await this.loadPreview(runId, true);
  }

async onPreviewFiltersChanged(filters: PreviewFilterState): Promise<void> {
    this.previewFilters = filters;
    if (this.preview) {
      await this.loadPreview(this.preview.runId);
    }
  }

public async applyPreview(runId: string, body: {
    remoteHash: string;
    expectedRevision?: number;
    approvedProposalIds: string[];
    manualMappings?: Array<{ localEntryId?: string; localEntryKey?: string; figshareSourceIds: string[] }>;
  }): Promise<FigshareApplyResult> {
    const response = await firstValueFrom(
      this.http.post(`${this.figshareUrl}/previews/${encodeURIComponent(runId)}/apply`, body, this.getJsonRequestOptions())
    );
    return this.unwrap<FigshareApplyResult>(response as ApiResponse<FigshareApplyResult>);
  }

public async listCrosswalks(query: { status?: string; sourceId?: string; localVocabularyId?: string } = {}): Promise<PagedResult<FigshareCrosswalkSummary>> {
    const params: Record<string, string> = {};
    for (const [key, value] of Object.entries(query)) {
      if (value) {
        params[key] = String(value);
      }
    }
    const response = await firstValueFrom(
      this.http.get(this.crosswalkUrl, { ...this.getJsonRequestOptions(), params })
    );
    return this.unwrapList<FigshareCrosswalkSummary>(response);
  }

private async loadCrosswalks(): Promise<void> {
    this.crosswalksLoading = true;
    try {
      const result = await this.api.listCrosswalks({ status: this.crosswalkStatusFilter || undefined });
      this.crosswalks = result.records;
      this.crosswalkTotal = result.total;
    } catch (err) {
      this.error = this.errorText('figshare-vocab-error-load-crosswalks', err);
      this.logger.error(this.error);
    } finally {
      this.crosswalksLoading = false;
    }
  }

async onCrosswalkStatusFilterChanged(status: string): Promise<void> {
    this.crosswalkStatusFilter = status;
    await this.loadCrosswalks();
  }

async approveCrosswalk(revision: number): Promise<void> {
    if (!this.activeCrosswalk) {
      return;
    }
    this.crosswalkSaving = true;
    this.crosswalkError = '';
    try {
      this.activeCrosswalk = await this.api.approveCrosswalk(this.activeCrosswalk.id, revision);
      this.crosswalkMessage = this.t('figshare-vocab-crosswalk-approved', 'Revision {{revision}} approved.', {
        revision,
      });
      await this.loadCrosswalks();
    } catch (err) {
      this.crosswalkError = this.errorText('figshare-vocab-error-approve', err);
      this.logger.error(this.crosswalkError);
    } finally {
      this.crosswalkSaving = false;
    }
  }

async deleteCrosswalk(crosswalk: FigshareCrosswalkSummary): Promise<void> {
    this.error = '';
    try {
      await this.api.deleteCrosswalk(crosswalk.id);
      this.message = this.t(
        'figshare-vocab-crosswalk-deleted',
        'Crosswalk removed. Both vocabularies were left intact.'
      );
      await this.loadCrosswalks();
    } catch (err) {
      this.error = this.errorText('figshare-vocab-error-delete-crosswalk', err);
      this.logger.error(this.error);
    }
  }

public async getCrosswalk(id: string): Promise<FigshareCrosswalkSummary> {
    const response = await firstValueFrom(
      this.http.get(`${this.crosswalkUrl}/${encodeURIComponent(id)}`, this.getJsonRequestOptions())
    );
    return this.unwrap<FigshareCrosswalkSummary>(response as ApiResponse<FigshareCrosswalkSummary>);
  }

public async getCrosswalkUsage(id: string): Promise<Array<{ brandName: string; configKey: string; bindingPath: string; outputs?: string }>> {
    const response = await firstValueFrom(
      this.http.get(`${this.crosswalkUrl}/${encodeURIComponent(id)}/usage`, this.getJsonRequestOptions())
    );
    return this.unwrap(response as ApiResponse<Array<{ brandName: string; configKey: string; bindingPath: string; outputs?: string }>>) ?? [];
  }

private async loadCrosswalkUsage(crosswalkId: string): Promise<void> {
    try {
      this.crosswalkUsage = await this.api.getCrosswalkUsage(crosswalkId);
    } catch (_err) {
      this.crosswalkUsage = [];
    }
  }

async openCrosswalk(crosswalk: FigshareCrosswalkSummary): Promise<void> {
    this.activeCrosswalk = crosswalk;
    this.mappingSearch = { q: '', status: '', offset: 0 };
    this.crosswalkError = '';
    this.crosswalkMessage = '';
    this.view = 'crosswalk-editor';
    await Promise.all([this.loadMappings(), this.loadCrosswalkUsage(crosswalk.id)]);
  }

public async listMappings(id: string, query: { q?: string; status?: string; revision?: number; limit?: number; offset?: number } = {}): Promise<PagedResult<FigshareCrosswalkMapping>> {
    const response = await firstValueFrom(
      this.http.get(`${this.crosswalkUrl}/${encodeURIComponent(id)}/mappings`, {
        ...this.getJsonRequestOptions(),
        params: this.toParams(query)
      })
    );
    return this.unwrapList<FigshareCrosswalkMapping>(response);
  }

private async loadMappings(): Promise<void> {
    if (!this.activeCrosswalk) {
      return;
    }
    this.mappingsLoading = true;
    try {
      const result = await this.api.listMappings(this.activeCrosswalk.id, {
        q: this.mappingSearch.q || undefined,
        status: this.mappingSearch.status || undefined,
        offset: this.mappingSearch.offset,
        limit: this.mappingPageSize,
      });
      this.mappings = result.records;
      this.mappingTotal = result.total;
    } catch (err) {
      this.crosswalkError = this.errorText('figshare-vocab-error-load-mappings', err);
      this.logger.error(this.crosswalkError);
    } finally {
      this.mappingsLoading = false;
    }
  }

private async loadCurrentTargets(localEntryId: string, localValue: string): Promise<void> {
    if (!this.crosswalkId) {
      return;
    }
    const requestId = ++this.currentTargetsRequestId;
    try {
      const result = await this.api.listMappings(this.crosswalkId, {
        q: localValue || undefined,
        revision: this.revision,
        limit: 200,
      });
      if (requestId !== this.currentTargetsRequestId) return;
      this.currentTargets = result.records
        .filter(mapping => mapping.localEntryId === localEntryId)
        .map(mapping => ({
          id: mapping.figshareCategoryId,
          label:
            mapping.figshareCategoryNumber == null
              ? mapping.figshareSourceId
              : `${mapping.figshareSourceId} (${mapping.figshareCategoryNumber})`,
        }));
    } catch (err) {
      this.logger.error('Failed to load the current targets of a local term', err);
      if (requestId === this.currentTargetsRequestId) this.currentTargets = [];
    }
  }

async onMappingSearchChanged(search: MappingSearchState): Promise<void> {
    this.mappingSearch = search;
    await this.loadMappings();
  }

private async saveMappingChange(change: MappingChangeRequest, successMessage: string): Promise<void> {
    if (!this.activeCrosswalk) {
      return;
    }
    this.crosswalkSaving = true;
    this.crosswalkError = '';
    this.crosswalkMessage = '';
    try {
      const updated = await this.api.saveMappings(this.activeCrosswalk.id, {
        revision: this.activeCrosswalk.workingRevision,
        changes: [change],
      });
      this.activeCrosswalk = updated;
      this.crosswalkMessage = successMessage;
      await this.loadMappings();
    } catch (err) {
      this.crosswalkError = this.errorText('figshare-vocab-error-save-mappings', err);
      this.logger.error(this.crosswalkError);
    } finally {
      this.crosswalkSaving = false;
    }
  }

async selectLocalEntry(entry: FigshareCrosswalkLocalEntry): Promise<void> {
    this.selectedLocalEntry = entry;
    this.selectedCategoryId = '';
    await this.loadCurrentTargets(entry.id, entry.value);
  }

async onMappingAdded(change: MappingChangeRequest): Promise<void> {
    await this.saveMappingChange(
      change,
      this.t('figshare-vocab-mapping-added', 'Target added to the working revision.')
    );
  }

async onMappingRemoved(change: MappingChangeRequest): Promise<void> {
    await this.saveMappingChange(
      change,
      this.t('figshare-vocab-mapping-removed', 'Mapping removed from the working revision.')
    );
  }

public async listCrosswalkLocalEntries(id: string, query: {
    q?: string;
    mapped?: 'mapped' | 'unmapped';
    revision?: number;
    limit?: number;
    offset?: number;
  } = {}): Promise<PagedResult<FigshareCrosswalkLocalEntry>> {
    const response = await firstValueFrom(
      this.http.get(`${this.crosswalkUrl}/${encodeURIComponent(id)}/local-entries`, {
        ...this.getJsonRequestOptions(),
        params: this.toParams(query)
      })
    );
    return this.unwrapList<FigshareCrosswalkLocalEntry>(response);
  }

private async loadLocalEntries(): Promise<void> {
    if (!this.crosswalkId) {
      return;
    }
    const requestId = ++this.localRequestId;
    this.localLoading = true;
    try {
      const result = await this.api.listCrosswalkLocalEntries(this.crosswalkId, {
        q: String(this.localSearchControl.value ?? '').trim() || undefined,
        mapped: this.unmappedOnly ? 'unmapped' : undefined,
        revision: this.revision,
        limit: PAGE_SIZE,
      });
      if (requestId !== this.localRequestId) {
        return;
      }
      this.localEntries = result.records;
      this.localTotal = result.total;
      this.localErrorMessage = '';
    } catch (err) {
      this.logger.error('Failed to load crosswalk local entries', err);
      this.localErrorMessage = this.t(
        'figshare-vocab-error-load-local-entries',
        'The local terms could not be loaded.'
      );
    } finally {
      if (requestId === this.localRequestId) {
        this.localLoading = false;
      }
    }
  }

async toggleUnmappedOnly(unmappedOnly: boolean): Promise<void> {
    this.unmappedOnly = unmappedOnly;
    await this.loadLocalEntries();
  }

public async saveMappings(id: string, body: {
    revision: number;
    changes: Array<{ op: 'add' | 'remove'; localEntryId: string; figshareCategoryId: string; matchType?: string; status?: string }>;
  }): Promise<FigshareCrosswalkSummary> {
    const response = await firstValueFrom(
      this.http.put(`${this.crosswalkUrl}/${encodeURIComponent(id)}/mappings`, body, this.getJsonRequestOptions())
    );
    return this.unwrap<FigshareCrosswalkSummary>(response as ApiResponse<FigshareCrosswalkSummary>);
  }

public async approveCrosswalk(id: string, revision: number): Promise<FigshareCrosswalkSummary> {
    const response = await firstValueFrom(
      this.http.post(`${this.crosswalkUrl}/${encodeURIComponent(id)}/approve`, { revision }, this.getJsonRequestOptions())
    );
    return this.unwrap<FigshareCrosswalkSummary>(response as ApiResponse<FigshareCrosswalkSummary>);
  }

public async deleteCrosswalk(id: string): Promise<void> {
    await firstValueFrom(
      this.http.delete(`${this.crosswalkUrl}/${encodeURIComponent(id)}`, this.getJsonRequestOptions())
    );
  }

public async list(query: VocabularyListQuery = {}): Promise<VocabularyListResult> {
    const url = `${this.brandingAndPortalUrl}/api/vocabulary`;
    const params: Record<string, string> = {};
    if (query.q && query.q.trim()) {
      params['q'] = query.q.trim();
    }
    if (query.type) {
      params['type'] = query.type;
    }
    if (query.source) {
      params['source'] = query.source;
    }
    if (typeof query.limit === 'number' && Number.isFinite(query.limit)) {
      params['limit'] = String(query.limit);
    }
    if (typeof query.offset === 'number' && Number.isFinite(query.offset)) {
      params['offset'] = String(query.offset);
    }
    if (query.sort && query.sort.trim()) {
      params['sort'] = query.sort.trim();
    }

    const response = await firstValueFrom(
      this.http.get<
        ApiResponse<ListAPIResponse<VocabularySummary>> |
        ListAPIResponse<VocabularySummary> |
        ApiResponse<VocabularyListResult> |
        VocabularyListResult |
        ApiResponse<{ data?: VocabularySummary[]; meta?: VocabularyListMeta }> |
        { data?: VocabularySummary[]; meta?: VocabularyListMeta }
      >(url, {
        ...this.getJsonRequestOptions(),
        params
      })
    );

    const asWrapped = response as ApiResponse<VocabularyListResult>;
    if (
      asWrapped &&
      typeof asWrapped === 'object' &&
      'data' in asWrapped &&
      asWrapped.data &&
      Array.isArray(asWrapped.data.data) &&
      asWrapped.data.meta
    ) {
      return asWrapped.data;
    }

    const listApiWrapped = response as ApiResponse<ListAPIResponse<VocabularySummary>>;
    if (
      listApiWrapped &&
      typeof listApiWrapped === 'object' &&
      'data' in listApiWrapped &&
      listApiWrapped.data &&
      Array.isArray(listApiWrapped.data.records)
    ) {
      const records = listApiWrapped.data.records;
      const summary = listApiWrapped.data.summary ?? {};
      const offset = Number(summary.start ?? query.offset ?? 0);
      const limit = Number(query.limit ?? records.length ?? 25);
      return {
        data: records,
        meta: {
          total: Number(summary.numFound ?? records.length),
          limit,
          offset
        }
      };
    }

    const listApiDirect = response as ListAPIResponse<VocabularySummary>;
    if (listApiDirect && typeof listApiDirect === 'object' && Array.isArray(listApiDirect.records)) {
      const records = listApiDirect.records;
      const summary = listApiDirect.summary ?? {};
      const offset = Number(summary.start ?? query.offset ?? 0);
      const limit = Number(query.limit ?? records.length ?? 25);
      return {
        data: records,
        meta: {
          total: Number(summary.numFound ?? records.length),
          limit,
          offset
        }
      };
    }

    const asDirect = response as VocabularyListResult;
    if (asDirect && typeof asDirect === 'object' && Array.isArray(asDirect.data) && asDirect.meta) {
      return asDirect;
    }

    const legacyWrapped = response as ApiResponse<{ data?: VocabularySummary[]; meta?: VocabularyListMeta }>;
    if (
      legacyWrapped &&
      typeof legacyWrapped === 'object' &&
      'data' in legacyWrapped &&
      legacyWrapped.data &&
      Array.isArray(legacyWrapped.data.data)
    ) {
      return {
        data: legacyWrapped.data.data,
        meta: legacyWrapped.data.meta ?? { total: legacyWrapped.data.data.length, limit: legacyWrapped.data.data.length, offset: 0 }
      };
    }

    const legacyDirect = response as { data?: VocabularySummary[]; meta?: VocabularyListMeta };
    if (legacyDirect && typeof legacyDirect === 'object' && Array.isArray(legacyDirect.data)) {
      return {
        data: legacyDirect.data,
        meta: legacyDirect.meta ?? { total: legacyDirect.data.length, limit: legacyDirect.data.length, offset: 0 }
      };
    }

    throw new Error(`Unexpected response from ${url}: ${this.describeUnexpectedResponse(response)}`);
  }

private async loadVocabularyPage(): Promise<void> {
    try {
      const response = await this.vocabularyApi.list({
        q: this.listQuery.searchTerm.trim() || undefined,
        source: this.listQuery.sourceFilter === 'all' ? undefined : this.listQuery.sourceFilter,
        type: this.listQuery.typeFilter === 'all' ? undefined : this.listQuery.typeFilter,
        limit: this.listLimit,
        offset: this.listOffset
      });
      this.vocabularies = response.data;
      this.totalVocabularyCount = Number(response.meta?.total ?? response.data.length);
      this.listLimit = Number(response.meta?.limit ?? this.listLimit);
      this.listOffset = Number(response.meta?.offset ?? this.listOffset);
    } catch (err) {
      this.error = this.t('admin-vocabulary-error-load-vocabularies', 'Failed to load vocabularies: {{error}}', { error: this.asErrorMessage(err) });
      this.logger.error(this.error);
    }
  }

async refresh(): Promise<void> {
    await this.loadVocabularyPage();
  }

async onListQueryChanged(query: VocabularyListQueryState): Promise<void> {
    this.listQuery = {
      ...query,
      searchTerm: String(query.searchTerm ?? '')
    };
    this.listOffset = 0;
    await this.loadVocabularyPage();
  }

async onListPageChanged(offset: number): Promise<void> {
    this.listOffset = Math.max(0, Number(offset) || 0);
    await this.loadVocabularyPage();
  }

protected override async initComponent(): Promise<void> {
    await this.refresh();
  }

async save(): Promise<void> {
    if (!this.canSave) {
      this.error = this.t('admin-vocabulary-error-name-required', 'Vocabulary name is required');
      return;
    }

    this.message = '';
    this.error = '';
    try {
      if (this.selectedVocabulary?.id) {
        await this.vocabularyApi.update(this.selectedVocabulary.id, this.draft);
        this.message = this.t('admin-vocabulary-message-updated', 'Vocabulary updated');
      } else {
        await this.vocabularyApi.create(this.draft);
        this.message = this.t('admin-vocabulary-message-created', 'Vocabulary created');
      }
      await this.refresh();
      this.closeEditModal();
    } catch (err) {
      this.error = this.t('admin-vocabulary-error-save-vocabulary', 'Failed to save vocabulary: {{error}}', { error: this.asErrorMessage(err) });
      this.logger.error(this.error);
    }
  }

private async deleteVocabulary(id: string): Promise<void> {
    if (!id) {
      return;
    }

    this.message = '';
    this.error = '';
    try {
      await this.vocabularyApi.delete(id);
      this.message = this.t('admin-vocabulary-message-deleted', 'Vocabulary deleted');
      if (this.selectedVocabulary?.id === id) {
        this.selectedVocabulary = null;
        this.selectedEntries = [];
        this.closeEditModal();
      }
      if (this.listOffset > 0 && this.vocabularies.length <= 1) {
        this.listOffset = Math.max(0, this.listOffset - this.listLimit);
      }
      await this.refresh();
    } catch (err) {
      this.error = this.t('admin-vocabulary-error-delete-vocabulary', 'Failed to delete vocabulary: {{error}}', { error: this.asErrorMessage(err) });
      this.logger.error(this.error);
    }
  }

async importRva(rvaId: string): Promise<void> {
    this.message = '';
    this.error = '';
    this.importStatusMessage = '';
    this.importStatusVariant = '';
    try {
      const trimmedId = String(rvaId ?? '').trim();
      if (!trimmedId) {
        this.error = this.t('admin-vocabulary-error-rva-id-required', 'RVA ID is required');
        this.importStatusMessage = this.error;
        this.importStatusVariant = 'danger';
        return;
      }

      this.isImportInProgress = true;
      this.importStatusMessage = this.t('admin-vocabulary-import-in-progress', 'Import in progress...');
      this.importStatusVariant = 'info';
      await this.vocabularyApi.importRva(trimmedId);
      this.message = this.t('admin-vocabulary-message-rva-imported', 'RVA vocabulary imported');
      this.importStatusMessage = this.t('admin-vocabulary-import-success', 'RVA vocabulary imported successfully.');
      this.importStatusVariant = 'success';
      await this.refresh();
      this.closeImportModal();
    } catch (err) {
      this.error = this.t('admin-vocabulary-error-import-rva', 'Failed to import RVA vocabulary: {{error}}', { error: this.asErrorMessage(err) });
      this.importStatusMessage = this.error;
      this.importStatusVariant = 'danger';
      this.logger.error(this.error);
    } finally {
      this.isImportInProgress = false;
    }
  }

async confirmSyncSelected(): Promise<void> {
    this.message = '';
    this.error = '';
    try {
      if (!this.selectedVocabulary?.id) {
        this.error = this.t('admin-vocabulary-error-no-selection', 'No vocabulary selected');
        return;
      }
      this.isSyncConfirmationOpen = false;
      this.isSyncInProgress = true;
      this.clearSyncStatusTimer();
      this.syncStatusMessage = this.t('admin-vocabulary-sync-in-progress', 'Sync in progress...');
      this.syncStatusVariant = 'info';
      const result = await this.vocabularyApi.sync(this.selectedVocabulary.id);
      this.message = this.t(
        'admin-vocabulary-sync-complete',
        'Sync complete (created={{created}}, updated={{updated}}, skipped={{skipped}})',
        { created: result.created, updated: result.updated, skipped: result.skipped }
      );
      await this.openVocabulary(this.selectedVocabulary.id);
      await this.refresh();
      this.syncStatusMessage = this.t('admin-vocabulary-sync-success', 'Sync completed successfully.');
      this.syncStatusVariant = 'success';
      this.scheduleSyncStatusClear();
    } catch (err) {
      this.error = this.t('admin-vocabulary-error-sync-vocabulary', 'Failed to sync vocabulary: {{error}}', { error: this.asErrorMessage(err) });
      this.syncStatusMessage = this.error;
      this.syncStatusVariant = 'danger';
      this.logger.error(this.error);
    } finally {
      this.isSyncInProgress = false;
    }
  }

async confirmDeleteVocabulary(): Promise<void> {
    if (!this.pendingDeleteVocabularyId) {
      this.closeDeleteVocabularyModal();
      return;
    }

    const id = this.pendingDeleteVocabularyId;
    this.closeDeleteVocabularyModal(false);
    try {
      await this.deleteVocabulary(id);
    } finally {
      this.restoreDeleteModalTrigger();
    }
  }

public async get(id: string): Promise<{ vocabulary: VocabularyDetail; entries: VocabularyEntry[] }> {
    const url = `${this.brandingAndPortalUrl}/api/vocabulary/${id}`;
    const response = await firstValueFrom(
      this.http.get<ApiResponse<{ vocabulary: VocabularyDetail; entries: VocabularyEntry[] }> | { vocabulary: VocabularyDetail; entries: VocabularyEntry[] }>(
        url,
        this.getJsonRequestOptions()
      )
    );
    return this.unwrap<{ vocabulary: VocabularyDetail; entries: VocabularyEntry[] }>(response);
  }

async openVocabulary(id: string): Promise<void> {
    this.message = '';
    this.error = '';
    this.rememberEditModalTrigger();
    try {
      const result = await this.vocabularyApi.get(id);
      const flattenedEntries = this.flattenEntries(result.entries);
      this.selectedVocabulary = result.vocabulary;
      this.selectedEntries = flattenedEntries;
      this.draft = {
        ...result.vocabulary,
        entries: flattenedEntries
      };
      this.clearSyncStatus();
      this.isSyncInProgress = false;
      this.isSyncConfirmationOpen = false;
      this.isEditModalOpen = true;
      this.isImportModalOpen = false;
    } catch (err) {
      this.error = this.t('admin-vocabulary-error-load-vocabulary', 'Failed to load vocabulary: {{error}}', { error: this.asErrorMessage(err) });
      this.logger.error(this.error);
    }
  }

