async previewCopyTo(): Promise<void> {
    const selection = this.selectedCopyGroups(this.copyTo.selection);
    const destinations = this.targets.filter((t) => this.copyTo.destinations.has(t.key)).map((t) => t.target);
    if (!this.selected || destinations.length === 0 || selection.length === 0) {
      this.copyTo.error = 'Choose at least one destination and one group of settings.';
      return;
    }
    this.copyTo.loading = true;
    this.copyTo.error = '';
    this.copyTo.preview = null;
    this.copyTo.acknowledged = new Set();
    try {
      this.copyTo.preview = await this.api.previewCopy(this.selected.target, destinations, selection.includes('all') ? ['all'] : selection);
    } catch (e) {
      this.copyTo.error = this.describeError(e, 'Could not preview the copy.');
    } finally {
      this.copyTo.loading = false;
    }
  }

async applyCopy(preview: DashboardCopyPreview, acknowledgedWarningIds: string[]): Promise<{ updated: number; revision: number }> {
    const body = {
      source: preview.source,
      destinations: preview.destinations,
      groups: preview.groups,
      expectedRevision: preview.expectedRevision,
      previewFingerprint: preview.previewFingerprint,
      acknowledgedWarningIds
    };
    return this.request(firstValueFrom(this.http.post<ApiResponse<{ updated: number; revision: number }>>(this.url('/copy/apply'), body, this.options())));
  }

async applyCopyTo(): Promise<void> {
    const preview = this.copyTo.preview;
    if (!preview || !this.canApplyCopyTo || !this.selected) {
      return;
    }
    const selected = this.selected;
    this.copyTo.loading = true;
    this.copyTo.error = '';
    try {
      const result = await this.api.applyCopy(preview, Array.from(this.copyTo.acknowledged));
      this.copyTo.open = false;
      if (this.selected?.key === selected.key) {
        if (preview.expectedRevision === this.baseRevision) {
          // The source is not a destination, so its settings remain current.
          this.baseRevision = result.revision;
        } else {
          // The source may have changed before preview; retain the draft and
          // its old revision so a later save cannot overwrite that change.
          this.staleConflict = true;
          this.error = 'Dashboard settings changed since this draft loaded. Reload saved settings before saving.';
        }
      }
      this.message = `Copied settings to ${result.updated} dashboard${result.updated === 1 ? '' : 's'}.`;
    } catch (e) {
      this.copyTo.error = this.describeError(e, 'Could not apply the copy. Nothing was changed.');
      if (e instanceof DashboardConfigApiError && (e.code === 'stale-preview' || e.code === 'stale-revision')) {
        this.copyTo.preview = null;
      }
    } finally {
      this.copyTo.loading = false;
    }
  }

private async getFormConfig(oid: string | null, recordType: string, editable: boolean, formName: string | null = null) {
    const ts = new Date().getTime().toString();

    const remainingPaths = oid ? `auto/${oid}` : `${recordType}`;
    const url = new URL(remainingPaths, `${this.brandingAndPortalUrl}/record/form/`);
    url.searchParams.set('ts', ts);
    url.searchParams.set('edit', editable?.toString() ?? 'false');
    if (formName) {
      url.searchParams.set('formName', formName?.toString());
    }

    type rawRespType = { data: FormConfigFrame; meta: Record<string, unknown>; prehydrate?: FormPrehydratePayload };
    const baseHeaders = this.requestOptions['headers'];
    const headers = (
      baseHeaders instanceof HttpHeaders
        ? baseHeaders
        : new HttpHeaders((baseHeaders ?? {}) as Record<string, string | string[]>)
    ).set('X-ReDBox-Api-Version', '2.0');
    const context = this.requestOptions['context'];
    const result = await firstValueFrom(
      this.http.get<rawRespType>(url.href, {
        headers,
        ...(context instanceof HttpContext ? { context } : {}),
        observe: 'response',
        responseType: 'json',
      })
    );
    this.loggerService.info(`Get form fields from url: ${url}`, result);
    if (!result.body) {
      throw new Error('Form config response body was empty.');
    }
    return { ...result.body, responseEntityTag: result.headers.get('ETag') };
  }

public async downloadFormComponents(oid: string, recordType: string, editMode: boolean, formName: string, modulePaths: string[]): Promise<FormComponentsMap> {
    // Get the form config from the server.
    // Includes the integrated model data (in componentDefinition.model.config.value) for rendering the form.
    const formConfigResp = await this.getFormConfig(oid, recordType, editMode, formName);
    const formConfig = formConfigResp?.data;
    const formConfigMeta = formConfigResp?.meta ?? {};
    const concurrency = parseFormLoadConcurrency(formConfigMeta, formConfigResp?.responseEntityTag);
    if (!formConfig) {
      throw new Error("Form config from server was empty.");
    }

    this.vocabTreeService.seedFromPayload(formConfigResp?.prehydrate);

    // This form config is the top of the lineage.
    const parentLineagePaths = this.buildLineagePaths({
      angularComponents: [],
      dataModel: [],
      formConfig: ['componentDefinitions'],
      layout: [],
    });

    // Resolve the field and component pairs
    const formMode: FormModesConfig = editMode ? 'edit' : 'view';
    return this.createFormComponentsMap(formConfig, parentLineagePaths, formConfigMeta, formMode, concurrency);
  }

public async downloadAndCreateFormComponents(formConfig?: FormConfigFrame): Promise<void> {
    if (!formConfig) {
      this.loggerService.info(`${this.logName}: creating form definition by downloading config`);
      this.formDefMap = await this.formService.downloadFormComponents(
        this.trimmedParams.oid(),
        this.trimmedParams.recordType(),
        this.editMode(),
        this.trimmedParams.formName(),
        this.modulePaths
      );
      // Store the form recordType if the recordType was not provided by the page.
      if (!this.trimmedParams.recordType() && this.formDefMap?.formConfig?.type) {
        this.recordType.set(this.formDefMap?.formConfig?.type);
      }
    } else {
      this.loggerService.info(`${this.logName}: creating form definition from provided config`);
      const parentLineagePaths = this.formService.buildLineagePaths({
        angularComponents: [],
        dataModel: [],
        formConfig: ['componentDefinitions'],
        layout: [],
      });
      this.formDefMap = await this.formService.createFormComponentsMap(formConfig, parentLineagePaths);
    }
    this.componentDefArr = this.formDefMap.components;
    // Host styling depends on the downloaded definition before nested fields finish initialising.
    this.requestRender();
    if (this.shouldRefreshDebugSnapshots()) {
      this.refreshTranslatedConfigDebugInfo(true);
      if (this.shouldRefreshComponentDebugInfo()) {
        this.refreshComponentDebugInfo();
      }
    }
    const compContainerRef: ViewContainerRef | undefined = this.componentsContainer;
    if (!compContainerRef) {
      throw new Error(`${this.logName}: No component container found. Cannot load components.`);
    }
    for (const componentDefEntry of this.componentDefArr) {
      const componentRef = compContainerRef.createComponent(FormBaseWrapperComponent);
      componentRef.instance.defaultComponentConfig = this.formDefMap?.formConfig?.defaultComponentConfig;
      componentRef.changeDetectorRef.detectChanges();

      await componentRef.instance.initWrapperComponent(componentDefEntry);
    }
    // Moved the creation of the FormGroup to after all components are created, allows for components that have custom management of their children components.
    await this.createFormGroup();
    this.captureLoadedRecordBaseline();
    // Dispatch load success action (R16.2, AC53)
    this.store.dispatch(FormActions.loadInitialDataSuccess({ data: this.form?.value || {} }));

    // Build the initial query source for component definitions
    this.setupQuerySource();
    // Initialize subscriptions to event bus
    this.initSubscriptions();
    // Behaviours subscribe before the ready event is published. This ordering is
    // deliberate and is the key runtime contract for form-level automation in v1.
    this.behaviourManager.bind(this);
    // Publish the form definition ready event
    this.eventBus.publish(createFormDefinitionReadyEvent({}));
    // Finally set the flag indicating components are loaded
    this.componentsLoaded.set(true);
  }

protected async initComponent(): Promise<void> {
    this.loggerService.info(
      `${this.logName}: Loading form with OID: ${this.trimmedParams.oid()}, on edit mode:${this.editMode()}, Record Type: ${this.trimmedParams.recordType()}, formName: ${this.trimmedParams.formName()}`
    );
    try {
      this.refreshRequestParamsFromUrl();
      this.configObj = await this.configService.getConfig();
      const viewAuditRolesVal = this.configObj?.['viewAuditRoles'];
      if (Array.isArray(viewAuditRolesVal) && viewAuditRolesVal.every(v => typeof v === 'string')) {
        this.viewAuditRoles.set(viewAuditRolesVal);
      }
      if (this.downloadAndCreateOnInit()) {
        await this.downloadAndCreateFormComponents();
      } else {
        this.loggerService.warn(
          `${this.logName}: downloadAndCreateOnInit is set to false. Form will not be loaded automatically. Call downloadAndCreateFormComponents() manually to load the form.`
        );
      }
    } catch (error) {
      this.loggerService.error(`${this.logName}: Error loading form`, error);
      // Dispatch load failure action instead of direct mutation
      const missingRecord =
        error instanceof HttpErrorResponse &&
        error.status === 404 &&
        /\/record\/(form|metadata)\//.test(error.url ?? '');
      const errorMsg = missingRecord ? 'missing-record' : 'form-load-error';
      this.store.dispatch(FormActions.loadInitialDataFailure({ error: errorMsg }));
    }
  }

public async getModelData(oid?: string, recordType?: string): Promise<Record<string, unknown>> {
    if (!oid && !recordType) {
      throw new Error("Must provide oid or recordType.")
    }

    const ts = new Date().getTime().toString();

    const url = oid
      ? new URL(`${this.brandingAndPortalUrl}/record/metadata/${oid}`)
      : new URL(`${this.brandingAndPortalUrl}/record/default/${recordType}`);
    url.searchParams.set('ts', ts);

    const result = await firstValueFrom(this.http.get<{ data: Record<string, unknown> }>(url.href, this.requestOptions));
    this.loggerService.info(`Get model data from url: ${url}`, result);
    return result?.['data'] ?? {};
  }

private async fetchVocabularyEntries(vocabRef: string, search: string, limit: number, offset: number, includeHistoricalValues: boolean): Promise<TypeaheadOption[]> {
        await this.waitForInit();
        const url = `${this.brandingAndPortalUrl}/vocab/${encodeURIComponent(vocabRef)}/entries`;
        const params: Record<string, string> = {
            search,
            limit: String(limit),
            offset: String(offset)
        };
        if (includeHistoricalValues) {
            params["includeHistoricalValues"] = "true";
        }
        const response = await firstValueFrom(
            this.http.get<WrappedResponse<Array<Record<string, unknown>>> | Array<Record<string, unknown>>>(url, {
                responseType: "json",
                observe: "body",
                context: this.httpContext,
                params
            })
        );

        const records = this.unwrapArrayResponse(response);
        return records
            .map((entry) => ({
                label: String(entry?.["label"] ?? ""),
                value: String(entry?.["value"] ?? ""),
                sourceType: "vocabulary" as const,
                historical: entry?.["historical"] === true,
                raw: entry
            }))
            .filter((entry) => Boolean(entry.label || entry.value));
    }

public searchVocabularyEntries(vocabRef: string, search: string, limit = 25, offset = 0, includeHistoricalValues = false): Promise<TypeaheadOption[]> {
        const trimmedVocabRef = String(vocabRef ?? "").trim();
        if (!trimmedVocabRef) {
            return Promise.reject(new Error("vocabRef is required"));
        }
        const trimmedSearch = String(search ?? "");
        const key = `vocab|${trimmedVocabRef}|${trimmedSearch}|${limit}|${offset}|${includeHistoricalValues ? 1 : 0}`;
        return this.dedupe(key, () => this.fetchVocabularyEntries(trimmedVocabRef, trimmedSearch, limit, offset, includeHistoricalValues));
    }

private async lookup(
    term: string,
    includeHistoricalValues = this.shouldIncludeHistoricalValues()
  ): Promise<TypeaheadOption[]> {
    const requestId = ++this.lookupRequestId;
    if (!this.validateConfiguration()) {
      return [];
    }
    const trimmedTerm = term.trim();
    if (trimmedTerm.length < this.minChars) {
      return [];
    }
    const cacheKey = `${this.sourceType}:${includeHistoricalValues ? 'historical' : 'current'}:${trimmedTerm}`;
    if (this.cacheResults && this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey) ?? [];
      if (requestId === this.lookupRequestId) {
        this.searchState = cached.length > 0 ? 'idle' : 'no-results';
      }
      return cached;
    }

    this.searchState = 'loading';
    this.statusMessage = '';
    try {
      let options: TypeaheadOption[] = [];
      if (this.sourceType === 'static') {
        options = await this.typeaheadDataService.searchStatic(trimmedTerm, this.staticOptions, this.maxResults);
      } else if (this.sourceType === 'vocabulary') {
        options = await this.typeaheadDataService.searchVocabularyEntries(
          this.vocabRef,
          trimmedTerm,
          this.maxResults,
          0,
          includeHistoricalValues
        );
      } else if (this.sourceType === 'external') {
        options = await this.typeaheadDataService.searchExternal(
          this.provider,
          trimmedTerm,
          this.resultArrayProperty,
          this.labelField,
          this.valueField
        );
      } else if (this.sourceType === 'service') {
        options = await this.typeaheadDataService.searchService(this.serviceId, trimmedTerm, 0, this.maxResults);
      } else {
        options = await this.typeaheadDataService.searchNamedQuery(
          this.queryId,
          trimmedTerm,
          0,
          this.maxResults,
          this.labelField,
          this.valueField
        );
      }
      options = this.filterHistoricalOptions(options);
      options = this.applyTemplateLabels(options);

      // A newer input value, blur, selection, or request invalidates this UI status,
      // although its options may still be safely cached below for a future lookup.
      if (requestId === this.lookupRequestId) {
        this.searchState = options.length > 0 ? 'idle' : 'no-results';
      }
      if (this.cacheResults) {
        this.cache.set(cacheKey, options);
      }
      return options;
    } catch (error) {
      this.loggerService.warn(`${this.logName}: typeahead lookup failed`, error);
      if (requestId === this.lookupRequestId) {
        this.searchState = 'error';
        this.statusMessage = '@form-typeahead-unable-to-fetch';
      }
      return [];
    }
  }

public readonly suggestions$: Observable<TypeaheadOption[]> = defer(() =>
    from(this.lookup(String(this.displayControl.value ?? '')))
  );

private async fetchNamedQuery(
        queryId: string,
        search: string,
        start: number,
        rows: number,
        labelField: string,
        valueField: string
    ): Promise<TypeaheadOption[]> {
        await this.waitForInit();
        const url = `${this.brandingAndPortalUrl}/query/vocab/${encodeURIComponent(queryId)}`;
        const response = await firstValueFrom(
            this.http.get<WrappedResponse<unknown> | unknown>(url, {
                responseType: "json",
                observe: "body",
                context: this.httpContext,
                params: {
                    search,
                    start: String(start),
                    rows: String(rows)
                }
            })
        );

        const records = this.extractNamedQueryRecords(response);
        return records
            .map((record) => {
                const label = this.getPathValue(record, labelField);
                const value = this.getPathValue(record, valueField);
                return {
                    label: String(label ?? ""),
                    value: String(value ?? label ?? ""),
                    sourceType: "namedQuery" as const,
                    raw: record
                };
            })
            .filter((entry) => Boolean(entry.label || entry.value));
    }

public searchNamedQuery(
        queryId: string,
        search: string,
        start = 0,
        rows = 25,
        labelField = "label",
        valueField = "value"
    ): Promise<TypeaheadOption[]> {
        const trimmedQueryId = String(queryId ?? "").trim();
        if (!trimmedQueryId) {
            return Promise.reject(new Error("queryId is required"));
        }
        const trimmedSearch = String(search ?? "");
        const resolvedLabelField = String(labelField ?? "").trim() || "label";
        const resolvedValueField = String(valueField ?? "").trim() || "value";
        const key = `namedQuery|${trimmedQueryId}|${trimmedSearch}|${start}|${rows}|${resolvedLabelField}|${resolvedValueField}`;
        return this.dedupe(key, () => this.fetchNamedQuery(trimmedQueryId, trimmedSearch, start, rows, resolvedLabelField, resolvedValueField));
    }

public async searchService(
        serviceId: string,
        search: string,
        start = 0,
        rows = 25
    ): Promise<TypeaheadOption[]> {
        await this.waitForInit();
        const trimmedServiceId = String(serviceId ?? "").trim();
        if (!trimmedServiceId) {
            throw new Error("serviceId is required");
        }

        const url = `${this.brandingAndPortalUrl}/service/vocab/${encodeURIComponent(trimmedServiceId)}`;
        const response = await firstValueFrom(
            this.http.post<WrappedResponse<Array<Record<string, unknown>>> | Array<Record<string, unknown>>>(url, {
                search: String(search ?? ""),
                start,
                rows
            }, {
                responseType: "json",
                observe: "body",
                context: this.httpContext
            })
        );

        const records = this.unwrapArrayResponse(response);
        return records
            .map((record) => ({
                label: String(record?.["label"] ?? ""),
                value: String(record?.["value"] ?? ""),
                sourceType: "service" as const,
                historical: record?.["historical"] === true,
                disabled: record?.["disabled"] === true,
                raw: record?.["raw"] ?? record
            }))
            .filter((entry) => Boolean(entry.label || entry.value));
    }

private async fetchExternal(
        provider: string,
