public async expandPath(vocabRef: string, notations: string[]): Promise<VocabTreeExpandPathResponse> {
    const trimmedVocabRef = String(vocabRef ?? "").trim();
    if (!trimmedVocabRef) {
      throw new Error("vocabRef is required");
    }

    const normalizedNotations = Array.from(
      new Set(
        (notations ?? [])
          .map((notation) => String(notation ?? "").trim())
          .filter((notation) => notation.length > 0)
      )
    );
    if (normalizedNotations.length === 0) {
      throw new Error("notation is required");
    }

    await this.waitForInit();

    const url = `${this.brandingAndPortalUrl}/vocab/${encodeURIComponent(trimmedVocabRef)}/expandPath`;
    const response = await firstValueFrom(
      this.http.get<unknown>(url, {
        responseType: "json",
        observe: "body",
        context: this.httpContext,
        params: {
          notation: normalizedNotations.join(",")
        }
      })
    );

    const parsed = this.parseExpandPathResponse(response, trimmedVocabRef);
    this.seedExpandPathCache(trimmedVocabRef, parsed.data);
    return parsed;
  }

private async expandToSelectedNodes(): Promise<void> {
    if (this.selectedByNotation.size === 0) {
      return;
    }

    if (this.inlineVocab) {
      const expandAncestors = (nodes: CheckboxTreeRenderNode[]): boolean => {
        let treeHasSelected = false;
        for (const node of nodes) {
          const childHasSelected = expandAncestors(node.children ?? []);
          const nodeIsSelected = this.isSelected(node);
          if (childHasSelected || nodeIsSelected) {
            this.expandedNodeIds.add(node.id);
            treeHasSelected = true;
          }
        }
        return treeHasSelected;
      };
      expandAncestors(this.rootNodes);
    } else {
      const notations = Array.from(this.selectedByNotation.keys());
      const canHydrateFromLoadedChildren = Array.from(this.selectedByNotation.values()).every(
        selected => Array.isArray(selected.genealogy) && selected.genealogy.length > 0
      );
      if (canHydrateFromLoadedChildren) {
        await this.expandToSelectedNodesLegacy();
        this.rootError = null;
        return;
      }
      try {
        const response = await this.vocabTreeService.expandPath(this.vocabRef, notations);
        const chains = Object.values(response.data ?? {});
        for (const chain of chains) {
          this.attachExpandedPath(chain);
        }
        this.rootError = null;
        this.applyDisplayLabels(this.rootNodes);
        this.rebuildIndexes(this.rootNodes, null);
      } catch (error) {
        if (this.isNotFoundError(error)) {
          await this.expandToSelectedNodesLegacy();
          this.rootError = null;
          return;
        }
        this.rootError = this.describeLoadError(error);
      }
    }
  }

protected override async initData(): Promise<void> {
    await this.prepareLabelTemplate();
    this.applyDisplayLabels(this.rootNodes);
    this.rebuildIndexes(this.rootNodes, null);
    if (!this.inlineVocab && this.rootNodes.length === 0 && this.vocabRef) {
      await this.loadRootNodes();
    }
    this.syncSelectionFromModel();
    await this.expandToSelectedNodes();
    this.focusedNodeId = this.rootNodes[0]?.id ?? null;
  }

private async runDisplaySyncFromModel(): Promise<void> {
    try {
      do {
        this.displaySyncQueued = false;
        this.syncSelectionFromModel();
        await this.expandToSelectedNodes();
      } while (this.displaySyncQueued);
    } finally {
      this.displaySyncInFlight = undefined;
      this.requestRender();
    }
  }

public async syncDisplayFromModel(): Promise<void> {
    if (this.displaySyncInFlight) {
      this.displaySyncQueued = true;
      return this.displaySyncInFlight;
    }
    this.displaySyncInFlight = this.runDisplaySyncFromModel();
    return this.displaySyncInFlight;
  }

private async fetchChildren(vocabRef: string, parentId: string): Promise<VocabTreeChildrenResponse> {
    await this.waitForInit();

    const url = `${this.brandingAndPortalUrl}/vocab/${encodeURIComponent(vocabRef)}/children`;
    const params: Record<string, string> = {};
    if (parentId) {
      params["parentId"] = parentId;
    }

    const response = await firstValueFrom(
      this.http.get<ApiResponse>(url, {
        responseType: "json",
        observe: "body",
        context: this.httpContext,
        params
      })
    );

    if (Array.isArray(response)) {
      return {
        data: response,
        meta: {
          vocabularyId: vocabRef,
          parentId: parentId || null,
          total: response.length
        }
      };
    }

    if (this.isValidVocabTreeChildrenResponse(response)) {
      return response;
    }

    const wrapped = response as WrappedResponse;
    if (Array.isArray(wrapped?.data) && wrapped.meta) {
      return { data: wrapped.data, meta: wrapped.meta };
    }

    throw new Error("Unexpected response from vocabulary children endpoint");
  }

public async getChildren(vocabRef: string, parentId?: string): Promise<VocabTreeChildrenResponse> {
    const trimmedVocabRef = String(vocabRef ?? "").trim();
    if (!trimmedVocabRef) {
      throw new Error("vocabRef is required");
    }
    const trimmedParentId = String(parentId ?? "").trim();
    const cacheKey = `${trimmedVocabRef}::${trimmedParentId}`;

    const cached = this.childrenCache.get(cacheKey);
    if (cached) {
      const response = await cached;
      if (!response.partial) {
        return response;
      }
      this.clearChildrenCacheEntry(trimmedVocabRef, trimmedParentId);
    }

    const pending = this.fetchChildren(trimmedVocabRef, trimmedParentId);
    this.childrenCache.set(cacheKey, pending);
    // Drop the cached promise on failure so the next caller gets a fresh attempt.
    pending.catch(() => this.childrenCache.delete(cacheKey));
    return pending;
  }

private async loadRootNodes(): Promise<void> {
    this.rootLoading = true;
    try {
      const response = await this.vocabTreeService.getChildren(this.vocabRef);
      this.rootNodes = this.toRenderNodes(response.data);
      this.rebuildIndexes(this.rootNodes, null);
    } catch (error) {
      this.rootError = this.describeLoadError(error);
    } finally {
      this.rootLoading = false;
    }
  }

private loadChildren(parent: CheckboxTreeRenderNode): Promise<void> {
    const existing = this.inFlightChildLoads.get(parent.id);
    if (existing) {
      return existing;
    }
    this.loadingNodeIds.add(parent.id);
    this.loadErrors.delete(parent.id);
    const pending = (async () => {
      try {
        const response = await this.vocabTreeService.getChildren(this.vocabRef, parent.id);
        parent.children = this.toRenderNodes(response.data);
        this.loadedNodeIds.add(parent.id);
        this.pathHydratedNodeIds.delete(parent.id);
        this.rebuildIndexes(parent.children, parent.id);
      } catch (error) {
        this.loadErrors.set(parent.id, this.describeLoadError(error));
      } finally {
        this.loadingNodeIds.delete(parent.id);
        this.inFlightChildLoads.delete(parent.id);
        this.requestRender();
      }
    })();
    this.inFlightChildLoads.set(parent.id, pending);
    return pending;
  }

public async toggleExpand(node: CheckboxTreeRenderNode, level: number): Promise<void> {
    if (!this.canExpand(node, level)) {
      return;
    }
    if (this.isExpanded(node)) {
      this.expandedNodeIds.delete(node.id);
      return;
    }
    this.expandedNodeIds.add(node.id);
    if (!this.inlineVocab && node.hasChildren && !this.loadedNodeIds.has(node.id)) {
      if (this.pathHydratedNodeIds.has(node.id)) {
        this.vocabTreeService.clearChildrenCacheEntry(this.vocabRef, node.id);
      }
      await this.loadChildren(node);
    }
  }

private async expandToSelectedNodesLegacy(): Promise<void> {
    // Each genealogy is sequential (the next parentId depends on the previous response),
    // but the chains for different selections are independent and can run in parallel.
    // The vocab service dedupes concurrent identical (vocabRef, parentId) requests, so
    // selections that share ancestors only trigger one network call per shared parent.
    const expansions = Array.from(this.selectedByNotation.values()).map(async selected => {
      const genealogy = selected.genealogy ?? [];
      let currentNodes = this.rootNodes;

      for (const notation of genealogy) {
        const node = currentNodes.find(n => this.nodeMatchesNotation(n, notation));
        if (!node) {
          break;
        }

        this.expandedNodeIds.add(node.id);
        if (node.hasChildren && (node.children?.length ?? 0) === 0 && !this.loadedNodeIds.has(node.id)) {
          await this.loadChildren(node);
        }
        currentNodes = node.children ?? [];
      }
    });
    await Promise.all(expansions);
  }

public onLabelClick(event: MouseEvent, node: CheckboxTreeRenderNode, level: number): void {
    this.focusedNodeId = node.id;
    if (!this.canExpand(node, level)) {
      return;
    }
    event.preventDefault();
    void this.toggleExpand(node, level);
  }

public onTreeKeydown(event: KeyboardEvent): void {
    const visible = this.getVisibleNodes();
    if (visible.length === 0) {
      return;
    }
    const focusedId = this.focusedNodeId ?? visible[0].id;
    const currentIndex = Math.max(
      0,
      visible.findIndex(node => node.id === focusedId)
    );
    const currentNode = visible[currentIndex];

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        this.focusedNodeId = visible[Math.min(currentIndex + 1, visible.length - 1)].id;
        break;
      case 'ArrowUp':
        event.preventDefault();
        this.focusedNodeId = visible[Math.max(currentIndex - 1, 0)].id;
        break;
      case 'ArrowRight':
        event.preventDefault();
        const currentLevel = this.getNodeLevel(currentNode.id);
        if (this.canExpand(currentNode, currentLevel)) {
          if (!this.isExpanded(currentNode)) {
            void this.toggleExpand(currentNode, currentLevel);
          } else if ((currentNode.children?.length ?? 0) > 0) {
            this.focusedNodeId = currentNode.children![0].id;
          }
        }
        break;
      case 'ArrowLeft':
        event.preventDefault();
        if (this.isExpanded(currentNode)) {
          this.expandedNodeIds.delete(currentNode.id);
        } else {
          const parentId = this.parentById.get(currentNode.id);
          if (parentId) {
            this.focusedNodeId = parentId;
          }
        }
        break;
      case ' ':
      case 'Enter':
        event.preventDefault();
        if (this.isSelectable(currentNode) && !this.isNodeDisabled(currentNode)) {
          this.onNodeChecked(currentNode, !this.isSelected(currentNode));
        }
        break;
      default:
        break;
    }
  }

