      this.selectedRun = detail;
      this.eventResponse = events;
    } catch (error) {
      this.selectedRun = null;
      this.eventResponse = this.emptyListResponse<HarvestRunEvent>();
      this.detailError = this.getErrorMessage(error, 'harvest-runs-error');
