    return this.executeLifecycleMutation('PURGE', oid, 'deleted', selected);
  }

public async deleteRecord(options?: DeleteEventConfig) {
    const oid = this.trimmedParams.oid();
    if (_isEmpty(oid)) {
      this.eventBus.publish(
        createFormDeleteFailureEvent({
          error: '@dmpt-form-delete-missing-oid',
          formScopeId: this.eventScopeId,
        })
      );
      return;
    }

    try {
      const concurrency = this.formMutationConcurrency(false);
      const requestBaseline = this.recordBaselineState();
      const response =
        Object.keys(concurrency).length > 0
          ? await this.recordService.delete(oid, concurrency)
          : await this.recordService.delete(oid);
      if (this.recordBaselineState() !== requestBaseline) {
        this.loggerService.warn(`${this.logName}: ignored a delete response after the form scope changed.`);
        return;
      }
      if (!response.wasPersisted()) {
        this.captureConflictResponse(response, requestBaseline);
        this.applyServerSaveProblems(response);
        const responseMessage = String(_get(response, 'message') ?? '');
        const errorMessage = responseMessage.startsWith('@') ? responseMessage : '@dmpt-form-delete-failed';

        this.eventBus.publish(
          createFormDeleteFailureEvent({
            error: errorMessage,
            requestId: response.requestId,
            formScopeId: this.eventScopeId,
          })
        );
      } else {
        this.formConflictState.set(null);
        this.eventBus.publish(
          createFormDeleteSuccessEvent({
            oid,
            response,
            formScopeId: this.eventScopeId,
            closeOnDelete: options?.closeOnDelete,
            redirectLocation: this.resolveRedirectLocation(options?.redirectLocation ?? '', oid),
            redirectDelaySeconds: options?.redirectDelaySeconds,
          })
        );
      }
    } catch (error: unknown) {
      this.loggerService.error(`${this.logName}: Error occurred while deleting form record:`, error);
      this.eventBus.publish(
        createFormDeleteFailureEvent({
          error: '@dmpt-form-delete-failed',
          formScopeId: this.eventScopeId,
        })
      );
    }
  }

private async resolveListMutationConcurrency(
    oid: string,
    representation: 'active' | 'deleted',
    concurrency: RecordMutationConcurrencyOptions,
    requestId: string
  ): Promise<RecordMutationConcurrencyOptions | RecordActionResult> {
    if (concurrency.entityTag !== undefined || concurrency.revision === undefined) {
      return concurrency;
    }
    if (!isRecordRevision(concurrency.revision)) {
      throw new TypeError('The selected record revision is invalid.');
    }

    const base = this.getHttpOptions() as { headers?: HttpHeaders; context?: HttpContext };
    const headers = (base.headers instanceof HttpHeaders ? base.headers : new HttpHeaders(base.headers ?? {})).set(
      'X-ReDBox-Api-Version',
      '2.0'
    );
    const readUrl =
      representation === 'deleted'
        ? `${this.brandingAndPortalUrl}/record/delete/${oid}`
        : `${this.brandingAndPortalUrl}/record/metadata/${oid}`;
    const response = await firstValueFrom(
      this.http.get<unknown>(readUrl, {
        headers,
        context: base.context,
        observe: 'response',
        responseType: 'json',
      })
    );
    const current = RecordActionResult.readConcurrency(response.body, response.headers);
    if (
      current.entityTag !== undefined &&
      current.revision !== undefined &&
      recordEntityTagRevision(current.entityTag) !== current.revision
    ) {
      return RecordActionResult.notDispatched('The record concurrency response was inconsistent.', oid, requestId);
    }
    if (current.revision !== concurrency.revision) {
      return RecordActionResult.preflightConflict(
        oid,
        requestId,
        'record-revision-stale',
        concurrency.revision,
        current
      );
    }
    if (!current.entityTag) {
      return RecordActionResult.preflightConflict(
        oid,
        requestId,
        'record-precondition-required',
        concurrency.revision,
        current
      );
    }
    return { ...concurrency, entityTag: current.entityTag };
  }

public async getReportConfig(name: string): Promise<any> {
    if (_isEmpty(name)) {
      this.loggerService.error(`getReportConfig() -> Parameter 'name' is empty!`);
      throw new Error('Report Config name is empty!');
    }
    const req = this.http.get(`${this.brandingAndPortalUrl}/admin/getReport?name=${name}`, this.reqOptsJsonBodyOnly);
    req.pipe(
      map((data:any) => {
        return data as ReportDto
      })
    );
    return firstValueFrom(req);
  }

protected async initComponent(): Promise<void> {
    const sysConfig = await this.configService.getConfig();
    const defaultDatePickerOpts = { dateInputFormat: 'DD/MM/YYYY', containerClass: 'theme-dark-blue' };
    const defaultDatePickerPlaceHolder = 'dd/mm/yyyy';
    this.datePickerOpts = ConfigService._getAppConfigProperty(sysConfig, this.appName, 'datePickerOpts', defaultDatePickerOpts);
    this.datePickerPlaceHolder = ConfigService._getAppConfigProperty(sysConfig, this.appName, 'datePickerPlaceHolder', defaultDatePickerPlaceHolder);
    this.brandingAndPortalUrl = this.reportService.brandingAndPortalUrl;
    _set(this.optTemplateData, 'brandingAndPortalUrl', this.brandingAndPortalUrl);
    this.recordsPerPage = ConfigService._getAppConfigProperty(sysConfig, this.appName, 'recordsPerPage', this.recordsPerPage);
    this.dateParamTz = ConfigService._getAppConfigProperty(sysConfig, this.appName, 'dateParamTz', this.dateParamTz);
    this.paginationMaxSize = ConfigService._getAppConfigProperty(sysConfig, this.appName, 'paginationMaxSize', this.paginationMaxSize);

    // Extract branding and portal from the URL for template loading
    this.branding = sysConfig.branding || '';
    this.portal = sysConfig.portal || '';

    // Load pre-compiled Handlebars templates for this report
    try {
      await this.handlebarsTemplateService.loadReportTemplates(this.branding, this.portal, this.reportName);
      this.loggerService.debug(`'${this.appName}': Loaded templates for report '${this.reportName}'`);
    } catch (error) {
      this.loggerService.error(`'${this.appName}': Failed to load templates for report '${this.reportName}':`, error);
    }

    this.report = await this.reportService.getReportConfig(this.reportName);
    this.tableHeaders = this.report.columns;
    this.initTracker.reportLoaded = true;
    await this.gotoPage(1);
    this.loggerService.debug(`'${this.appName}' ready!`);
  }

public async getReportResult(name: string, pageNum:number, params:any, rows:number = 10): Promise<any> {
    if (_isEmpty(name)) {
      this.loggerService.error(`getReportResult() -> Parameter 'name' is empty!`);
      throw new Error('Report name is empty!');
    }
    let start = (pageNum-1) * rows;
    var url = `${this.brandingAndPortalUrl}/admin/getReportResults?name=${name}&start=${start}&rows=${rows}`;
    for(var key in params) {
      url=url+'&'+key+"="+params[key];
    }
    const req = this.http.get(url, this.reqOptsJsonBodyOnly);
    req.pipe(
      map((data:any) => {
        return data as ReportResultDto
      })
    );
    return await firstValueFrom(req);
  }

async gotoPage(pageNum: number): Promise<RecordPageDto> {
    this.initTracker.resultsReturned = false;
    this.reportResult =  await this.reportService.getReportResult(this.reportName, pageNum, this.getParams(), this.recordsPerPage);
    this.initTracker.resultsReturned = true;
    return this.reportResult;
  }

