private async initRoleResolution(): Promise<void> {
    try {
      await this.userService.waitForInit();
      const res = await this.userService.getInfo();
      const user = (res as any)?.user ?? res;
      const userRoles = (user?.roles ?? []) as Array<{ name?: string }>;
