    this.loading = true;
    this.loadError = '';
    try {
      const response = await this.workspaceTypeService.getWorkspaceTypes();
      if (!response.status) throw new Error('Workspace types request was unsuccessful.');
      this.mergeWorkspaceTypes(response.workspaceTypes);
    } catch (error) {
      this.loadError = 'Unable to load workspace types';
      this.loggerService.warn(`${this.logName}: ${this.loadError}. Using configured defaults.`, error);
    } finally {
      this.loading = false;
    }
  }

async getWorkspaceType(name: string): Promise<WorkspaceTypeDefinition> {
    await this.waitForInit();
    const response = await firstValueFrom(
      this.http.get<unknown>(
        `${this.brandingAndPortalUrl}/workspaces/types/${encodeURIComponent(name)}`,
        this.reqOptsJsonBodyOnly
      )
    );
    const data = this.unwrapData(response) as Record<string, unknown>;
    const candidate = (data?.['workspaceType'] ?? data) as unknown;
    if (!this.isWorkspaceType(candidate)) {
      throw new Error(`Workspace type '${name}' was not returned by the server.`);
    }
    return { ...candidate };
  }

